namespace QuickCode.QuickCode.Portal.Helpers
{
    /// <summary>
    /// Indexes page grants once per permission group (5 min sliding).
    /// Grant Manager updates call <see cref="InvalidatePermissionGroup"/> so the next request reloads from the API.
    /// </summary>
    public class CachedPortalPagePermissionManager : IPortalPagePermissionManager
    {
        private const string PermissionItemPrefix = "PortalViewPermission:";
        private const string MapCachePrefix = "PortalPagePermissionMap:";

        private readonly IHttpContextAccessor httpContextAccessor;
        private readonly IPortalPageAccessGrantsClient portalPageAccessGrantClient;
        private readonly IMemoryCache memoryCache;

        public CachedPortalPagePermissionManager(
            IPortalPageAccessGrantsClient portalPageAccessGrantClient,
            IHttpContextAccessor httpContextAccessor,
            IMemoryCache memoryCache)
        {
            this.portalPageAccessGrantClient = portalPageAccessGrantClient;
            this.httpContextAccessor = httpContextAccessor;
            this.memoryCache = memoryCache;
        }

        public async Task<ViewPermission> GetPagePermission(string currentController, string viewName)
        {
            var lookupName = PortalPagePermissionManager.ResolvePermissionLookupName(currentController, viewName);
            var httpContext = GetHttpContext();
            var itemKey = PermissionItemPrefix + lookupName;

            if (httpContext.Items[itemKey] is ViewPermission cached)
                return cached;

            var map = await GetPermissionMapAsync();
            if (!map.TryGetValue(lookupName, out var authorization))
                authorization = new ViewPermission();

            httpContext.Items[itemKey] = authorization;
            return authorization;
        }

        public void InvalidatePermissionGroup(string permissionGroupName)
        {
            if (string.IsNullOrWhiteSpace(permissionGroupName))
                return;

            memoryCache.Remove(MapCachePrefix + permissionGroupName);
            httpContextAccessor.HttpContext?.Session.Remove("PortalPageAccessGrants");
        }

        private async Task<Dictionary<string, ViewPermission>> GetPermissionMapAsync()
        {
            var groupName = SessionGroupName ?? string.Empty;
            var cacheKey = MapCachePrefix + groupName;
            if (memoryCache.TryGetValue(cacheKey, out Dictionary<string, ViewPermission> map) && map != null)
                return map;

            var grants = await GetPortalPageAccessGrant();
            map = IndexGrants(grants);
            memoryCache.Set(cacheKey, map, new MemoryCacheEntryOptions
            {
                SlidingExpiration = TimeSpan.FromMinutes(5)
            });
            return map;
        }

        private static Dictionary<string, ViewPermission> IndexGrants(
            List<GetPortalPageAccessGrantsResponseDto> grants)
        {
            var map = new Dictionary<string, ViewPermission>(StringComparer.Ordinal);
            foreach (var grant in grants)
            {
                var action = grant.PageAction.ToString();
                var key = grant.PortalPageDefinitionKey;
                if (string.IsNullOrEmpty(key) || !key.EndsWith(action, StringComparison.Ordinal))
                    continue;

                var lookupName = key[..^action.Length];
                if (!map.TryGetValue(lookupName, out var authorization))
                {
                    authorization = new ViewPermission { IsPageAvailable = true };
                    map[lookupName] = authorization;
                }

                authorization.IsPageAvailable = true;
                authorization.GetType().GetProperty(action)?.SetValue(authorization, true, null);
            }

            return map;
        }

        private async Task<List<GetPortalPageAccessGrantsResponseDto>> GetPortalPageAccessGrant()
        {
            AttachBearer();
            return (await portalPageAccessGrantClient
                    .PortalPageAccessGrantsGetPortalPageAccessGrantsAsync(SessionGroupName))
                ?.Where(g => g.IsActive)
                .ToList() ?? [];
        }

        private HttpContext GetHttpContext()
        {
            AttachBearer();
            return httpContextAccessor.HttpContext!;
        }

        private void AttachBearer()
        {
            if (httpContextAccessor.HttpContext?.User.Identity?.IsAuthenticated != true)
                return;

            var accessToken = PortalApiTokenStore.GetAccessToken(httpContextAccessor.HttpContext);
            if (!string.IsNullOrEmpty(accessToken))
                ((ClientBase)portalPageAccessGrantClient).SetBearerToken(accessToken);
        }

        public string SessionGroupName
        {
            get
            {
                return GetHttpContext().User.Claims
                    .FirstOrDefault(i => i.Type == ClaimTypes.GroupSid)?.Value;
            }
        }
    }
